            "AlwaysTrue": {"Fn::Equals": ["x", "x"]},
            "AlwaysFalse": {"Fn::Equals": ["x", "y"]},
            "Dynamic": {"Fn::Equals": [{"Ref": "Env"}, "prod"]},
